; modes.asm -- chapter 17: one interrupt in each mode
; generated by gen17.py
        INCLUDE "msx.inc"
        OUTPUT "modes.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
; The same interrupt taken in the three modes, one frame each: mode 2
; through the table, mode 1 to the BIOS's routine at $0038, and mode 0, which
; runs the instruction it finds on the bus. Each waits with HALT.
init:   di
        ld sp, SYS_AREA
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr2
        ld (IM2_JUMP), a
        ld hl, isr2
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
e2:     in a, (VDP_CTRL)        ; no signal left over from before
        ei
        halt                    ; mode 2: the address in the table
        di
        im 1
e1:     in a, (VDP_CTRL)
        ei
        halt                    ; mode 1: $0038
        di
        im 0
e0:     in a, (VDP_CTRL)
        ei
        halt                    ; mode 0: the byte on the bus
        di
stop:   jr stop

; isr2: mode 2's routine: the status read, and back
isr2:   in a, (VDP_CTRL)        ; the VDP takes its signal down
        ei
        ret
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
